export default [{"id":336,"question":"ما حكم الإبرة في العضل أو الوريد في رمضان، وهي للعلاج وتسكين الألم؟","title":"حكم الإبرة في العضل أو الوريد للصائم","answer":"الجواب: الصحيح أنه لا حرج فيها، لكن إذا أجَّلها إلى الليل يكون أحوط، وإلا فلا تُبطل الصوم، وإبر العضل أقلّ وأسهل، ما دامت لإسكان الألم فلا بأس، أو لتخدير العضو حتى يُعالج؛ لا بأس، أما إبر التَّغذية فإنها تُفطّر.","link":"https://binbaz.org.sa/fatwas/4424/حكم-الابرة-في-العضل-او-الوريد-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0389.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":337,"question":"ما حكم سحب الدم للتَّحليل؟","title":"حكم سحب الدم من الصائم للتحليل","answer":"الجواب: كذلك لا حرج فيه، سحب الدم للتَّحليل الصحيح أنه لا حرج فيه؛ لأنه شيء قليل لا يُشبه الحجامة.\nس: ولو كثر؟\nالشيخ: الغالب أنه يكون قليلًا، أما إذا كان للتَّبرع لإسعاف المرضى فهذا ينبغي له القضاء إذا دعت الحاجة، وإن تيسر تأجيله إلى الليل فهو أوْلى، إذا كَثُر فالقضاء أحوط.","link":"https://binbaz.org.sa/fatwas/4425/حكم-سحب-الدم-من-الصاىم-للتحليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0390.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":1612,"question":"إذا أخرج الإنسانُ وهو صائم القلسَ عمدًا هل يُفطر به؟","title":"ما أثر القيء على الصوم؟","answer":"الجواب:\nنعم، النبي ﷺ قال: مَن ذرعه القَيْءُ فلا قضاءَ عليه، ومَن استقاء فعليه القضاء بنصِّ الحديث.","link":"https://binbaz.org.sa/fatwas/21716/ما-اثر-القيء-على-الصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة صوم من ذرعه القيء.mp3","categories":["مفسدات الصيام"]},{"id":1618,"question":"النُّخامة إذا كانت في الحلق وتعمّدتُ جمعها في الحلق ومن ثَمَّ ابتلعتُها وأنا صائم، فما الحكم؟","title":"ما حكم ابتلاع الدم والنخامة ونحوها للصائم؟","answer":"الجواب:\nكأنَّك عندك وساوس، في الحلق ما تضرّ، وإذا وصلت للفم ما يجوز بلعها، تَلْفظْها، أمَّا إذا راحت من الحلق ما يضرّ.\nس: إذا جمعتُها في الفم تعمُّدًا؟\nج: إذا راحت من الحلق ما يضرّ، جمعتَها أو ما جمعتَها، ما دامت في الحلق ما بعد صارت خارجًا.\nس: استنشقتُ الماء في يوم وأنا صائم ومن ثَمَّ دخل إلى الحلق؟\nج: إذا كنتَ ما تعمّدت ما عليك شيء، لكن السنة عدم المبالغة للصائم، لا يُبالغ في الاستنشاق.\nس: طلع من المعدة إلى الحلق ثم تعمّدتُ بلعه مرةً أخرى؟\nج: ما دام ما خرج ما يضرّ.\nس: حكم الدم إذا نزل في الفم ثم تعمّدتُ ابتلاعه؟\nج: إذا تعمّدت تُفطر إذا وصل للفم.\nس: في حكم الاستنشاق سألتُ شيخنا وقال: إنَّك تُفطر؟\nج: لا، إذا تعمّدتَ ابتلاع الدم تُفطر.\nس: في حكم استنشاق الماء؟\nج: إذا كان على طريق الاستنشاق ولكن غلبك الماء.\nس: سألتُ شيخنا وقلتُ له: استنشقتُ ولم أتعمد ودخل إلى الحلق.\nج: ما يضرّ.\nس: قال: يفطر؟\nج: لا، ما يفطر، ما عنده خبر، إذا ما تعمّدتَ فلا شيء عليك.\nس: ما نأخذ بقوله يعني؟\nج: ما عليك شيء.","link":"https://binbaz.org.sa/fatwas/21722/ما-حكم-ابتلاع-الدم-والنخامة-ونحوها-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في الصيام.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":2652,"question":"المُغَذِّيَّات التي تُوضع للمريض مع الدم هل تُفَطِّر الصائم؟","title":"حكم المُغَذِّيَّات التي تُوضع للمريض الصائم","answer":"الجواب: نعم؛ تُفَطِّر إلا الشيء القليل، مثل التحليل يُعفى عنه، التحليل الذي يؤخذ من الأصبع أو غيره يُعفى عنه، والمغذي يُفَطِّر .","link":"https://binbaz.org.sa/fatwas/22788/حكم-المغذيات-التي-توضع-للمريض-الصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المغذية التي توضع للمريض الصائم.mp3","categories":["مفسدات الصيام"]},{"id":4163,"question":"أكل ظانًّا بقاء الليل، أو أكل ظانًّا بقاء النهار؟","title":"ما حكم صوم مَنْ أكل ظانًّا بقاء الليل؟","answer":"الجواب: الصحيح أنه يقضي، لو أكل في الصباح يحسب أنَّ الليل باقٍ، ثم بان أنه أكل نهارًا؛ يقضي، هذا الذي عليه جمهورُ أهل العلم، وهكذا لو ظنَّ أن الشمس غربت، ثم بانت؛ عليه القضاء عند الجمهور.\nس: بعضهم يقول: ما الدليل؟\nج: الدليل أنه بان أنه في النهار، وهو واجبٌ عليه أن يصوم النهار كله، وظهر أنه أكل في النهار، وكان من واجبه ألا يفرط، من واجبه أن يجتهد ويحتاط ولا يعجل في الفطر ولا يُؤخّر الأكل، ثم أيضًا هذا باب إذا فُتح عظم فيه البلاء والتَّساهل.\nس: حصل مرةً مع الرسول ﷺ؟\nج: قيل: إنهم قضوا، وقيل: لم يقضوا، من حديث أسماء، قال بعضُ السلف: لا بدّ من قضاءٍ، فالجمهور على القضاء، وبعضهم قال: لا قضاء.","link":"https://binbaz.org.sa/fatwas/24417/ما-حكم-صوم-من-اكل-ظانا-بقاء-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من أكل ظانًّا بقاء الليل.mp3","categories":["مفسدات الصيام"]},{"id":5269,"question":"ما حكم استنشاق البخور والطِّيب للصائم؟","title":"ما حكم استنشاق البخور والطِّيب للصائم؟","answer":"الجواب: لا ينبغي أن يستنشق؛ لأن بعض أهل العلم يرى أن يبطل الصيام، لكن إذا شمّ الإنسان الطيب في المسجد أو في البيت من غير استنشاق ما يضر، الحمد لله، أما أن يستنشق البخور فهذا بعض أهل العلم يرى أنه يفطّر، فيبنغي تركه.[1]","link":"https://binbaz.org.sa/fatwas/30879/ما-حكم-استنشاق-البخور-والطيب-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/waza2ef_ramadan. 03.mp3","categories":["مفسدات الصيام"]},{"id":5877,"question":"لو أنزل المذي يا شيخ؟","title":"حكم خروج المذي والمني من الصائم","answer":"الجواب: المذي ما يضر على الصحيح، المذي ما يضر على الصحيح؛ لأنه يخرج سريعًا، وليس مثل المني، المذي شيء يخرج من الذكر عند تحرك الشهوة، وهو لا يضر الصيام على الصحيح، بعض العلماء يقول: إنه يفطر الصائم، ولكن الصحيح أنه لا يفطر الصائم، ولا يضر. السؤال: الأخ يقول: لو أمنى؟ الجواب: إذا أمنى عليه الإعادة، يفطره المني، وعليه أن يعيد ذلك اليوم، يقضيه، ولا عليه كفارة. الكفارة في الوطء، أما من سبقه المني بسبب العادة السرية -والعياذ بالله- أو بسبب أنه قبلها، وهو سريع المني؛ فإنه يقضي ذلك اليوم، وليس عليه كفارة، ولكن عليه القضاء، والحذر في المستقبل من التساهل في هذا الأمر.","link":"https://binbaz.org.sa/fatwas/1217/حكم-خروج-المذي-والمني-من-الصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_214.mp3","categories":["الحيض والنفاس","مفسدات الصيام","قضايا المرأة"]},{"id":5908,"question":"هل الحجامة تفسد الصوم، أم هي منسوخة؟","title":"حكم الاحتجام للصائم","answer":"الجواب: هذا فيه خلاف بين أهل العلم، منهم من رآها تبطل الصوم لحديث أفطر الحاجم والمحجوم، ومنهم من رآها لا تفطر لحديث أنس وغيره أنه كانوا لا يكرهونها إلا من أجل الضعف. وقد اختلف العلماء في ذلك، والمشهور أنها تفطر الصوم، وأن آخر الأمرين من النبي ﷺ أنها تفطر الصائم، ولكن الخلاف قائم فيها، والحجة من الجانبين قوية؛ فالأولى من المؤمن أن يتباعد عنها أثناء الصيام، يحتاط لدينه، ولا يحتجم إلا في الليل.","link":"https://binbaz.org.sa/fatwas/1241/حكم-الاحتجام-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_238.mp3","categories":["الحيض والنفاس","مفسدات الصيام","قضايا المرأة"]},{"id":7026,"question":"هناك امرأة صامت رمضان، ولكن قبل الغروب نزل منها دم، فتكمل الصوم وإلا تفطر، مع العلم أن الدم ليس حيض؛ لأنه أتى بعد العادة الشهرية، فما يكون صومها؟","title":"حكم صيام المرأة إذا خرج منها دم قبل الغروب","answer":"الجواب:\n\nإذا كانت المرأة صائمة، ونزل بها الحيض قبل الغروب، أو الدم الذي يعتبر حيضًا قبل الغروب؛ بطل الصوم.\n\nأما إذا كان بعد الغروب، بعدما غابت الشمس؛ فصومها صحيح، ولو قبل أن تصلى المغرب، ما دام بعد إفطارها بعد غروب الشمس، صومها صحيح.\n\nأما إن كان قبل الغروب، والدم يعتبر حيضًا؛ فإنه يبطل صومها، أما إن كان لا، صفرة، وكدرة؛ هذا لا يبطل الصوم، تقول: أم عطية -رضي الله عنها وهي من الصحابيات-: كنا لا نعد الكدرة، والصفرة بعد الطهر شيئًا، لكن إذا نزل الدم؛ فالأصل في الدم أنه حيض، قد .. تطهر، ثم يعود علها الدم، لكن إذا كان صفرة، أو كدرة بعد الطهارة، هذا لا يضرها.","link":"https://binbaz.org.sa/fatwas/3003/حكم-صيام-المراة-اذا-خرج-منها-دم-قبل-الغروب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1411.mp3","categories":["الحيض والنفاس","مفسدات الصيام","قضايا المرأة"]},{"id":7588,"question":"هذه الرسالة وردت من جدة نزلة بني مالك يقول: أنا المرسل مهلهل سهيل المطيري ، يقول كان في يوم من أيام رمضان المبارك هذه السنة ألف وأربعماية، أصابني ضيق في صدري بسبب انسداد فتحة الأنف مما جعلني أستعمل قطرة في الأنف يومان، ونزلت إلى حلقي القطرة، فهل يجوز أن أقضي ذلك اليومين التي استعملت فيها القطرة، علماً أني لم أفطر إلى الليل متمسك بصيامي، أفيدوني أثابكم الله، وجزاكم الله عنا وعن المسلمين أفضل الجزاء؟","title":"حكم صيام من استعمل قطر الأنف ووجد طعمها في حلقه","answer":"الجواب: الذي تعاطى القطرة حتى وصلت إلى حلقه ينبغي له أن يقضي؛ لأن كثيراً من أهل العلم يرى صومه يبطل بذلك، فإذا وصلت القطرة إلى حلقه فالأولى والأحوط له القضاء خروجاً من خلاف العلماء، وينبغي له تأجيل القطرة في مثل هذا إلى الليل إذا تيسر تأجيل القطرة والاكتحال والدواء إلى الليل فهو يكون أفضل وأحوط، فإن استعمله في النهار لشدة الحاجة فلا بأس، لكن إن وصل الطعم إلى الحلق أفطر وإلا فلا، صومه صحيح ولا يقضي، أما الذي وصل طعم القطرة إلى حلقه فإنه يقضي ذلك على سبيل الاحتياط والخروج من خلاف العلماء.","link":"https://binbaz.org.sa/fatwas/4641/حكم-صيام-من-استعمل-قطر-الانف-ووجد-طعمها-في-حلقه ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_019/01906.mp3","categories":["مفسدات الصيام"]},{"id":7621,"question":"سؤاله الأخير يقول: في شهر رمضان الكريم مع أذان الفجر، أو أثناء أذان الفجر، هل يسمح بشرب الماء قبل إنهاء الأذان، وفقكم الله؟","title":"حكم الأكل والشرب أثناء أذان الفجر من رمضان","answer":"الجواب: إذا كان الصائم لم يعلم أن الأذان على الصبح، بل كما يؤذن الناس على التحري وعلى الساعة والتقويم، فلا بأس أن يشرب وهو يؤذن أو يأكل لقمة في يده وهو يؤذن، لا بأس بهذا؛ لأن الأذان يخبر عن الصبح، مظنة الصبح، ليس براءي للصبح وإنما يخبر عن ما عرفه بالساعة أو بالتقويم، وقد يكون الصبح خرج وقد يكون ما خرج، والله جل وعلا إنما أوجب الإمساك بالتبين، فينبغي للمؤمن أن يحتاط وينتهي من سحوره قبل الفجر، قبل الأذان حتى لا يقع في شبهة، لكن لو قدر أنه أكل شيئاً يسيراً مع الأذان أو شرب حال الأذان، فالظاهر أنه لا حرج عليه في ذلك إذا كان لم يعلم أن الصبح قد طلع .نعم.","link":"https://binbaz.org.sa/fatwas/4674/حكم-الاكل-والشرب-اثناء-اذان-الفجر-من-رمضان ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_024/02404.mp3","categories":["مفسدات الصيام"]},{"id":7643,"question":"أيضاً يقول: هل الجنابة تبطل الصيام أم لا؟","title":"آثار الجنابة على صيام رمضان","answer":"الجواب: الجنابة لها حالات: إن كانت الجنابة وقعت في الليل، بأن جامع أهله في آخر الليل -مثلاً- ثم أصبح قبل أن يغتسل فلا حرج، والصوم صحيح، والنبي ﷺ كان يأتي أهله ثم يصبح جنباً ويغتسل بعد الصباح عليه الصلاة والسلام، أما إن كانت الجنابة في النهار، يعني: جامع أهله في النهار، فهذا آثم وعاص لربه ، والصوم يبطل وعليه كفارة، إذا كان تعمد ذلك عليه كفارة عتق رقبة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكيناً، لكل مسكين نصف صاع من قوت البلد، هذه هي الكفارة في حق من أتى أهله في رمضان في النهار، وصومه يبطل، وعليه القضاء قضاء ذلك اليوم الذي جامع فيه أهله في النهار، أما إذا كان الجماع في الليل ولكنه أصبح جنباً لم يغتسل فلا حرج في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/4781/اثار-الجنابة-على-صيام-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_035/03504.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":7653,"question":"طيب لو أنزل بدون جماع في هذه الحالة؟","title":"حكم الصائم إذا أنزل بدون إيلاج","answer":"الجواب: يقضي اليوم ولا شيء عليه، إذا أنزل المني فعليه قضاء اليوم، يصوم هذا اليوم، ويستمر صائم فيه لا يفطر، يستمر صائماً ويمسك، ولكن يقضيه بعد ذلك إذا كان مني، أما إذا كان مذي: الماء اللزج الذي يخرج عند الشهوة، هذا الصحيح أنه لا يضر بالصوم ولا عليه شيء، المذي نفسه، الذي هو ماء لزج يخرج عند حدوث الشهوة، هذا يسمى المذي، هذا لا يضر على الصحيح، أما إذا أنزل المني المعروف فهذا هو الذي يقضى. نعم.\nالمقدم: ولكن كفارة عليه؟\nالشيخ: ولا كفارة إلا بجماع، إذا جامع عليه كفارة.","link":"https://binbaz.org.sa/fatwas/4791/حكم-الصاىم-اذا-انزل-بدون-ايلاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_036/03604.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":7881,"question":"سماحة الشيخ عبد العزيز! لدينا مجموعة كبيرة من رسائل السادة المستمعين، نبدؤها برسالة عبد الله الحماد الصالح ويسأل عن الإنزال في رمضان دون جماع، ورسالة المستمع (س. م. ش) ويسأل عن حكم التبرج، وهذه رسالة عبد الله الحماد الصالح يقول في رسالته هذه: السلام عليكم ورحمة الله وبركاته، وبعد: أرجو عرض رسالتي هذه على سماحة الشيخ عبدالعزيز بن عبدالله بن باز يقول: في شهر رمضان المبارك الذي انصرم نمت مع زوجتي على الفراش، وضميتها بدون أن أواقعها فعليًّا، أي: بدون جماع، الأمر الذي أودعني أنزل بدون مباشرة، أرجو إفادتي ما هو الحكم؟ وما هي الكفارة؟ ولكم تحياتي.","title":"حكم الإنزال في نهار رمضان","answer":"الشيخ: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا شك أن الجماع في صيام رمضان وفي كل صيام واجبٍ: غيرُ جائز ويبطل الصيام، أما الملامسة والتقبيل والمباشرة فلا حرج في ذلك، فقد كان النبي صلى الله عليه وسلم يباشر وهو صائم ويقبل وهو صائم عليه الصلاة والسلام، ولكن إذا كان الإنسان سريع الشهوة ويخشى من المباشرة أو التقبيل نزول المني فالأولى به أن يتباعد عن ذلك ولا يتساهل في هذا الشيء، فإن ضم زوجته إليه أو قبلها أو لمسها ثم خرج منه المني فإنه يجب عليه الغسل من جهة المني وقضاء ذلك اليوم إذا كان في النهار، وليس عليه كفارة، إنما الكفارة فيما إذا جامعها، أما مجرد ضمها إليه أو تقبيلها أو ما أشبه ذلك من الملامسة هذا كله جائز ولا حرج فيه فعله النبي صلى الله عليه وسلم ورخص فيه اللهم صل عليه وسلم، ولكن إذا كان من طبعه سرعة الشهوة فالأولى به التباعد عن هذا الشيء حتى لا يقع في المحذور، وإذا نزل المني فإن عليه قضاء ذلك اليوم، يفسد الصوم وعليه قضاء ذلك اليوم، وليس عليه كفارة، هذا هو الحكم، يقضي اليوم ويغتسل من الجنابة لأنه يوجب الغسل ولكن ليس عليه قضاء[1]، والمرأة كذلك مثله إن أنزلت بضمها أو بلمسها أو تقبيلها إن أنزلت منيٍّا فعليها الغسل وقضاء ذلك اليوم، وليس عليها كفارة، وإن لم تنزل ليس عليها شيء. نعم.\n\n\n\tلعل الشيخ رحمه الله قصد: (وليس عليه كفارة)، كما هو الظاهر من السياق.","link":"https://binbaz.org.sa/fatwas/5350/حكم-الانزال-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_058/05801.mp3","categories":["مفسدات الصيام","قضاء الصيام","الجماع في نهار رمضان"]},{"id":7912,"question":"أيضاً لديها سؤال آخر، تقول: لقد صمت يوماً من أيام رمضان ولم يبق من ذلك اليوم إلا خمس دقائق عن موعد الإفطار وجاءتني الدورة الشهرية، فهل يجب علي أن أصلي صلاة المغرب قضاء بعد أن أطهر أم لا؟","title":"حكم من جاءتها الدورة قبل غروب الشمس في رمضان","answer":"الجواب: مادامت الدورة جاءتها قبل غروب الشمس فليس عليها صلاة المغرب ولا غيرها، والصوم لا يصح ذاك اليوم الذي جاء فيه الحيض قبل أن تغيب الشمس فإن الصوم يبطل وعليها قضاؤه، هذا إذا كانت تعلم أنها جاءتها قبل غروب الشمس ولو بخمس دقائق. نعم.","link":"https://binbaz.org.sa/fatwas/5394/حكم-من-جاءتها-الدورة-قبل-غروب-الشمس-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_062/06203.mp3","categories":["الحيض والنفاس","مفسدات الصيام","قضايا المرأة"]},{"id":8728,"question":"الرسالة التالية وصلت إلى البرنامج من المستمع (أ. س. ب. ن) أخونا يقول: أبعث لكم برسالتي هذه متضمنة مشكلتي وهي أنني وقعت في أهلي نهار رمضان ثلاث مرات في ثلاثة أيام من ذلك الشهر قبل ست سنوات تقريبًا، وقد ندمت على فعلتي تلك، وقد كنت أظن أن كفارة ذلك هي إطعام فقط، ومن ثم أهملت ذلك لعدة سنوات ظنًا مني أنه يجوز لي أن أطعم في أي وقت أشاء، وفي الفترة الأخيرة علمت حقيقة الكفارة، فما رأي فضيلتكم، هل يجوز لي أن أطعم عشرة مساكين عن كل يوم، أم ماذا؟ وهل على زوجتي أيضًا كفارة؟ وهل هناك فرق بين كونها مكرهة أو غير مكرهة، جزاكم الله خيرًا؟","title":"حكم من جامع امرأته في نهار رمضان","answer":"الجواب: الواجب عليكما جميعًا التوبة والاستغفار والندم على ما وقع؛ لأن الله حرم على الصائم تناول المفطرات ومن أشدها الجماع، فلا يجوز للمؤمن حال صومه رمضان وهو صحيح مقيم أن يتناول المفطرات لا الجماع ولا غيره، ولا يجوز له أيضًا أن يكره زوجته على ذلك، وليس لها أن تطاوعه على ذلك، بل يجب عليها أن تمتنع، وعليكما الكفارة جميعًا وهي: عتق رقبة مؤمنة عن كل واحد منكما عن كل يوم، يعني: ثلاث رقاب عن كل يوم رقبة وعنها كذلك، فالجميع ست رقاب عليك ثلاث وعليها ثلاث عن الأيام الثلاثة، إذا كانت مطاوعة غير مكرهة.\nفإن عجزتما فعليكما صيام شهرين متتابعين كل واحد يصوم شهرين متتابعين عن كل جماع في يوم، فعليك ستة أشهر عن الأيام الثلاثة وعليها ستة أشهر عن الأيام الثلاثة إلا أن تكون مكرهة يعني: أكرهتها بالقوة حتى لم تستطع منعك.\nفإن عجزتما عن العتق والصيام فعليكما إطعام ستين مسكينًا عن كل جماع، يعني: عن كل يوم وقع فيه الجماع، فالمعنى: إطعام ثلاث كفارات ستين مسكينًا يعني: ثلاث مرات، ثلاثين صاعًا، وثلاثين صاعًا، وثلاثين صاعًا؛ تسعين صاعًا توزع بين ستين مسكينًا، كل مسكين له صاع ونصف، عن كل يوم نصف صاع، وعليها مثل ذلك إذا كانت مطاوعة، تسعون صاعًا عن الأيام الثلاثة، عن كل يوم ثلاثين صاعًا لستين فقيرًا، هذه التسعون الصاع تسلم لستين فقيرًا، يعني: تدفع إليهم كل واحد يعطى صاع ونص عن الثلاثة الأيام، كل نصف صاع عن يوم، ونصف الصاع كيلو ونصف تقريبًا، يعني: أربعة كيلو ونص عن الثلاثة الأيام من الحنطة أو من الرز أو من التمر من قوت البلد، هذا هو الواجب عليكما مع التوبة والاستغفار والندم وعدم العودة إلى مثل هذا، وأنتما أعلم بحالكما، فمع الاستطاعة يجب العتق، ومع العجز الصيام، ومع العجز عن الصيام الإطعام هو الأخير.\nالله يهدينا جميعًا لما يرضيه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6880/حكم-من-جامع-امراته-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_161/16103.mp3","categories":["الجماع في نهار رمضان","مفسدات الصيام"]},{"id":8786,"question":"الرسالة التالية وصلت إلى البرنامج من المستمع الذي رمز إلى اسمه بـ: (س . ع النبهان )، خميس مشيط، يقول في رسالته وفي سؤاله: إنني أود أن أعرف ماذا يجب على من استمنى عمداً في نهار شهر رمضان، وهل ينطبق عليه قول الرسول الكريم ﷺ: من أفطر متعمداً فلن يقبل منه صيام الدهر كله، وإن صامه أفيدونا أفادكم الله؟","title":"ماذا يجب على من استمنى في نهار رمضان؟","answer":"الجواب: أولاً: الاستمناء لا يجوز، لا في رمضان ولا في غيره، الاستمناء محرم ومنكر، عند جمهور أهل العلم لا يجوز فعله، لما فيه من مخالفة قوله تعالى: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ ۝ فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُوْلَئِكَ هُمُ الْعَادُونَ [المؤمنون:5-7] فالاستمناء غير إتيان الزوجة وغير إتيان ملك اليمين، فهو عبث ومنكر، وهو عدوان.\nثانياً: فيه مضار كثيرة، مع كونه مخالفاً للشرع، فقد قرر الأطباء العارفون بهذه الجريمة، قرروا أن فيها مضار كثيرة على المستمني.\nثالثاً: على من استمنى في رمضان أن يقضي اليوم، عليه أن يتوب إلى الله، وعليه أن يقضي ذلك اليوم؛ لأنه أفطر فيه بهذا الاستمناء، يعني صار في حكم المفطرين وإن لم يأكل ويشرب؛ لكنه صار في حكم المفطرين، فعليه القضاء، قضاء اليوم.\nرابعاً: أما حديث: من أفطر يوم في رمضان لم يكفر عنه صوم الدهر وإن صامه فهو حديث ضعيف عند أهل العلم مضطرب الرواية، ليس بثابت، ولو ثبت لكان معناه عند أهل العلم الزجر والتحذير من الإفطار بغير حق، وليس معناه أنه لا يقضي، لا. بل معناه الزجر عن تعاطي الإفطار بغير حق، والصواب أنه مضطرب ليس بثابت، وعلى من أفطر بالاستمناء أو بغيره أن يتوب إلى الله ويندم، ويبادر بالقضاء، عليه أن يقضي ما عليه مع التوبة والاستقامة، وليس عليه كفارة، فالكفارة تختص بمن جامع في رمضان خاصة، أما الاستمناء في رمضان، أو الأكل عمداً، أو الشرب عمداً في رمضان، فهذا يوجب القضاء ويوجب التوبة والرجوع إلى الله والإنابة إليه، وليس يوجب الكفارة، فافهم يا أخي واحذر. نعم.","link":"https://binbaz.org.sa/fatwas/6947/ماذا-يجب-على-من-استمنى-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_220/22010.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":9186,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: صفية محمد من لحج في اليمن، أختنا لها مجموعة من الأسئلة من بينها هذا  هل يجوز الاستنشاق والمضمضة في نهار رمضان لمن كان صائماً؟","title":"حكم المضمضة والاستنشاق في نهار رمضان","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد:\nفقد ثبت عن رسول الله عليه الصلاة والسلام أنه قال: وبالغ في الاستنشاق إلا أن تكون صائماً، أمر بإسباغ الوضوء ثم قال: وبالغ في الاستنشاق إلا أن تكون صائماً دل ذلك على أن الصائم يتمضمض ويستنشق لكن لا يبالغ مبالغة يخشى منها نزول الماء إلى جوفه، أما الاستنشاق فلابد منه، وهكذا المضمضة لأنهما فرضان في الوضوء في حق الصائم وغيره. نعم.","link":"https://binbaz.org.sa/fatwas/7346/حكم-المضمضة-والاستنشاق-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_151/15101.mp3","categories":["مفسدات الصيام","فروض الوضوء وصفته"]},{"id":9270,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الرياض وباعثها أحد الإخوة يقول: أخوكم في الله (م. ع. ح) أخونا يقول: كنت من قبل أربع سنوات من الآن من الشباب الطيبين وملتزم بالصلاة والسنة، ولكنني صاحبت جلساء سوء وبدأت أترك هذا الطريق حتى أصبحت أتهاون في أداء الصلاة، وارتكبت إحدى المعاصي في نهار رمضان منذ حوالي ثلاث سنوات، وبدأت من العام الماضي أشعر بذنبي ورجعت إلى ما كنت عليه باتباع السنة وإقامة الصلاة، ولكن كل ما تذكرت الذي عملته في نهار رمضان خاصة عند قيامي لصلاة الفجر حزنت وبدأت عيناي تذرف من الدموع، فأرجو من سماحة الشيخ توضيح ما يجب علي أن أفعله، هل هو صيام أم قضاء وجزاكم الله خير الجزاء.والواقع يذكر بالتفصيل خطيئته التي ارتكبها في نهار رمضان سماحة الشيخ؟","title":"حكم من فعل العادة السرية في نهار رمضان","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالحمد لله الذي هداك -يا أخي- للرجوع إلى الصواب، ولزوم طريق السنة والجماعة، وصحبة الأخيار، ومن تاب تاب الله عليه، وهذا الذي أصابك من الحزن على ما حصل منك من الانتكاس هذا يدل على خير عظيم، فأبشر بالخير والتوبة يمحو الله بها ما قبلها، من تاب تاب الله عليه، يقول النبي ﷺ: التائب من الذنب كمن لا ذنب له ويقول ﷺ: التوبة تهدم ما كان قبلها فالتوبة تهدم ما جرى منك من تقصير والحمد لله، وهذا الحزن إذا ذكرت سيئتك والبكاء هذا خير عظيم وفائدة كبيرة، وهذا منك من جنس ما قال بعض السلف: إن العبد ليفعل الذنب فيدخل به الجنة، ويفعل الحسنة فيدخل بها النار، قيل: كيف ذلك؟ قال: يفعل الحسنة فيعجب بها ويتكبر بها ويتعاظم بها فيدخل بها النار، ويفعل السيئة ثم يندم كلما ذكرها ويحزن كلما ذكرها فيدخل بها الجنة.\nفأنت بهذه التوبة وبهذا الندم وبهذا الحزن يرجى لك الخير العظيم، ويرجى قبول توبتك، فأنت على خير عظيم.\nأما ما جرى منك في رمضان فعليك عنه الكفارة مع التوبة الصادقة، تصوم اليوم الذي جرى فيه الجماع تقضيه وعليك الكفارة عن الجماع، وهي عتق رقبة إن كنت تستطيع، فإن عجزت صمت شهرين متتابعين، فإن عجزت أطعمت ستين مسكينًا، ثلاثين صاعًا، وأنت أعلم بنفسك، إذا استطعت أن تعتق رقبة توجد في بعض الجهات الإفريقية أرقاء بالتوارث موجودين يباعون وقد اشترينا من ذلك جملة وأعتقناها، وإن عجزت عن ذلك فالصيام شهرين متتابعين فإن لم تستطع أطعمت ستين مسكينًا، كل مسكين يعطى نصف الصاع من التمر أو الأرز أو غيرهما من قوت البلد، ونصف الصاع يقارب كيلو ونصف من الحنطة ونحوها.\nوهذا هو الواجب عليك مع التوبة والاستغفار ومع قضاء اليوم، والمرأة مثله، المرأة كذلك إذا كانت صائمة بالغة المقصود أن عليها مثلك، عليها التوبة والاستغفار وقضاء اليوم وعليها مع ذلك الكفارة إذا كانت مطاوعة، أما إذا كانت مقهورة مغصوبة لا قدرة لها فليس عليها شيء. نعم.\nالمقدم: قد أضطر للتصريح سماحة الشيخ الموضوع ليس موضوع جماع مع طرف آخر، هو ما يسمى بالعادة السرية عند الشباب؟\nالجواب: ما هو جماع؟ العادة السرية لا، العادة السرية ما فيها إلا قضاء ما فيها كفارة، العادة السرية فيها القضاء فقط، قضاء اليوم والتوبة والاستغفار والحمد لله.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7433/حكم-من-فعل-العادة-السرية-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_183/18301.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":9555,"question":"هذا (م. أ. س) من عفيف بعث إلينا بهذه الرسالة يقول: في رمضان بعد أذان الصبح قمت بجماع زوجتي لكنني لم أعرف بأن الأذان قد حصل، وبعد نصف ساعة تأكدت بأنه فعلاً قد أذن لصلاة الصبح فماذا علي في هذه الحالة؟","title":"حكم من جامع زوجته بعد أذان الفجر في رمضان جاهلاً","answer":"الجواب: عليك قضاء اليوم وعليها قضاء اليوم، وعليك التوبة لأنك ما تثبت ما أخذت بالحيطة، فعليك التوبة إلى الله وعليك قضاء اليوم، وعليكما الكفارة وهي عتق رقبة مؤمنة فإن لم تستطيعا فصيام شهرين متتابعين كل واحد منكما.. عليك رقبة وعليها رقبة، فإن لم تستطيعا فصيام شهرين متتابعين عليك وعليها كل واحد عليه صيام شهرين متتابعين إلا أن تكون مجبورة إلا أن تكون أكرهتها بالغصب والقوة فالإثم عليك وليس عليها شيء، فإن لم تستطيعا للصيام فإطعام ستين مسكين عليك وعليها ثلاثين صاع عليك وثلاثين صاع عليها، ستين صاع عليكما جميعًاَ لستين فقيراً كل واحد يعطى صاع نصفه عنك ونصفه عنها، هذا هو الواجب عليكما مع التوبة والاستغفار ومع قضاء اليوم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7720/حكم-من-جامع-زوجته-بعد-اذان-الفجر-في-رمضان-جاهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_270/27004.mp3","categories":["الجماع في نهار رمضان","مفسدات الصيام"]},{"id":9828,"question":"هذا محسن حسين المسعودي من بلدة البدع الشمالية، بعث بهذه الرسالة، يقول: إن والدي من البادية الرحل ويقوم بتربية المواشي، وأنا كنت أقوم برعاية الأغنام عنده، وفي يوم من أيام رمضان المبارك وأنا أرعى في الأغنام قابلتني فتاة كذلك ترعى أغنامها، وكان الوقت ما بين الظهر والعصر، وجلست معها، وأخذت في مبادلتي للحديث ووصل ذلك إلى المزاح والمداعبة في أثناء ذلك اليوم الذي هو في شهر رمضان، فحصل مني ما حصل دون أن أقرب هذه الفتاة، يسأل عن حكم ذلك في نهار رمضان؟","title":"حكم من داعب أجنبية في نهار رمضان حتى أنزل","answer":"الجواب: أما من ناحية الحكم فهو لا يجوز؛ لأنها أجنبية وليس له أن يحادثها محادثة تجب الشهوة وربما أغرت إلى الفتنة والزنا، بل يجب التحرز من ذلك.\n\nأما الحديث العابر الذي ليس فيه إثم وليس فيه ما يجر إلى الفاحشة كسؤالها عن أهلها، أو سؤالها عن المرعى الطيب، أو عن الماء أو ما أشبه ذلك من الأمور التي ليس فيها ما يجر إلى فتنة هذا لا بأس به.\n\nوأما المداعبة والأشياء التي تتعلق بالفاحشة وتدلي إلى الزنا وتسبب الوقوع في المنكر هذه أشياء لا تجوز.\n\nأما الصوم فهو صحيح صومه صحيح إذا كان لا يخرج منه مني.\n\nالمقدم: لا هو ذكر أنه أنزل.\n\nالشيخ: أما إذا كان أنزل فإن عليه أن يقضي اليوم؛ فإنه يفطر هذا لأنه بإنزاله المني يفطر صومه، أما المذي فلا يفطر على الصحيح، المذي هو الماء اللزج الذي يخرج عند آثار الشهوة هذا لا يفطر الصوم على الصحيح من أقوال العلماء.\n\nأما المني فإنه يفطر صومه وعليه قضاء.\n\nالمقدم: لكن لا يلزمه كفارة.\n\nالشيخ: وليس عليه كفارة الكفارة، الكفارة في الجماع خاصة.","link":"https://binbaz.org.sa/fatwas/8002/حكم-من-داعب-اجنبية-في-نهار-رمضان-حتى-انزل","audio":"https://files.zadapps.info/binbaz.org.sa/%D8%AD%D9%83%D9%85%20%D9%85%D8%AF%D8%A7%D8%B9%D8%A8%D8%A9%20%D8%A7%D9%84%D9%85%D8%B1%D8%A3%D8%A9%20%D8%A7%D9%84%D8%A3%D8%AC%D9%86%D8%A8%D9%8A%D8%A9%20%D9%81%D9%8A%20%D9%86%D9%87%D8%A7%D8%B1%20%D8%B1%D9%85%D8%B6%D8%A7%D9%86.mp3","categories":["مفسدات الصيام","قضاء الصيام"]},{"id":9829,"question":"يقول: ذهبت إلى دار والدي وأكملت صيامي في ذلك اليوم؛ خوفاً من والدي أن يسألني عن سبب إفطاري، علماً أنه كان عمري في تلك اللحظة حول خمسة عشر سنة والآن عمري يقارب خمسة وأربعين سنة، وأنا الآن أصلي وأصوم وأؤدي جميع فروض الله هو السؤال الذي يمكن أن يؤخذ من عبارته هذه أنه يقول: ذهبت إلى دار والدي وأكملت صيامي، هل من أفطر في الإنزال أو ما شابهه هل يجوز له أن يأكل؟الشيخ: هذا الرجل هو صاحب السؤال الأول؟المقدم: نعم هو صاحب السؤال الأول.","title":"حكم الأكل والشرب لمن أفطر في رمضان بإنزال المني","answer":"الجواب: نعم يلزمه إكمال الصوم ولو أنزل يلزمه إكمال الصوم الذي نزل حصل به حصل له شيء يفطر صيامه ليس له أن يستمر في الإفطار، بل عليه أن يمسك لحرمة الزمن، الزمن محترم زمن صيام، فمن ابتلي بشيء يفطره فإنه لا يجوز له الاستمرار في الفطر، بل يلزمه الإمساك حتى تغيب الشمس ويقضي مع ذلك، فلو أنزل المني بسبب المداعبة والقبلة لزوجته أو في الحرام نعوذ بالله فإنه يقضي هذا اليوم ومع هذا عليه الإمساك وإكمال الصوم، ولا يجوز له أن يقول: أنا ما دام أفطرت بالمني آكل وأشرب لا، عليه أن يكمل صومه ويمسك ومع هذا عليه القضاء، نعم.","link":"https://binbaz.org.sa/fatwas/8003/حكم-الاكل-والشرب-لمن-افطر-في-رمضان-بانزال-المني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_261/26104.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":9872,"question":"وهذه رسالة وردت من (ح. ر. د. الحربي ) من الطائف -الحوية- يقول في رسالته: قبل أربع سنوات تقريباً وقعت على زوجتي في يوم من أيام رمضان، وأنا في ذلك الوقت جاهل عن ذلك وبعدها تعلمت والحمد لله، وعرفت أنه لا يجوز هذا في رمضان، فسؤالي: ما هي الكفارة التي أؤديها علماً أنني تبت إلى الله ؟","title":"كفارة من جامع زوجته في نهار رمضان","answer":"الجواب: الذي يطأ زوجته في رمضان، عليه التوبة إلى الله ، وعليه الكفارة، والكفارة هي: عتق رقبة مؤمنة، فإن لم يستطع صام شهرين متتابعين، فإن عجز أطعم ستين مسكيناً ثلاثين صاعاً، كل صاع بين اثنين، هذا هو الواجب على من أتى زوجته في رمضان، وإن عجز عن الصيام والإطعام سقط عنه ذلك لفقره وشدة حاجته، وما دام يستطيع فإنه يكفر بواحدة من هذه الثلاث:\nأولاً: عتق رقبة، يعني: رقبة مؤمنة يعتقها إن قدر، فإن عجز صام شهرين متتابعين، فإن عجز عن ذلك أطعم ستين مسكيناً، لكل مسكين نصف صاع من تمر من رز، من حنطة يعني: من قوت البلد، ثلاثين صاعاً بين ستين فقيراً، كل فقير له نصف الصاع، وهو يقارب: كيلو ونصف تقريباً نصف الصاع، ولو كان فقيراً لا يستطيع بالكلية، فإنه لا شيء عليه إن شاء الله، لما جاء في الحديث الصحيح عن النبي ﷺ أنه أفتى من سأله عن ذلك بما ذكر، فلما قال الفقير: إنه ليس في المدينة أهل بيت أحوج إلى الطعام مني، قال: أطعمه أهلك، وكان طعاماً أهدي للنبي ﷺ فسلمه له عليه الصلاة والسلام ليتصدق به، فقال الرجل: يا رسول الله! ليس بين لابتي المدينة أهل بيت أحوج إلى الطعام منا، فضحك عليه الصلاة والسلام، وقال: أطعمه أهلك اللهم صل عليه وسلم. نعم. يعني: ولم يأمره بالقضاء، ولم يأمره بقضاء الطعام نعم، وعليهما صوم اليوم أيضاً، على الزوجة والزوج صوم اليوم الذي حصل فيه الجماع، وعليها مثله من الكفارة، إذا كانت مطاوعة غير مكرهة، فعليها مثله من الكفارة. نعم.\nالمقدم: بارك الله فيكم يسأل أيضاً صاحبنا الحربي من الطائف ويقول في هذه الرسالة: طلقت زوجتي بعد مشاكل حصلت بيننا، وبعد أن ذهبت إلى أهلها أقمت دعوى عليها، وبعد ثلاث جلسات للمحاولة في إرجاعها إلى بيتي رفضت ثم طلقتها طلقة واحدة أمام القاضي، علماً أن لي منها ثلاثة أطفال، وهي عند أهلها الآن والأطفال معي في البيت، وأنا طابت نفسي منها، لكن هل الطلقة الواحدة تكفي، علماً أن القاضي أعطاها صكاً بذلك، أم أن أطلقها مرة ثانية؟\nالجواب: تكفي الطلقة التي أعطيتها والحمد لله، تكفي ولا تطلق زيادة. نعم.\nالمقدم: بارك الله فيكم وأثابكم الله.","link":"https://binbaz.org.sa/fatwas/8033/كفارة-من-جامع-زوجته-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_263/26302.mp3","categories":["الجماع في نهار رمضان","مفسدات الصيام"]},{"id":10214,"question":"أيضاً تقول: يقول البعض لدينا: إن اللبان لا يفطر، فهل هذا القول صحيح؟","title":"حكم مضغ اللبان للصائم","answer":"الجواب: ليس بصحيح، اللبان إذا كان يعالجه ويبلع ريقه، هذا شبه الطعام؛ لأن له طعم وله ذوق، مثل الذي يمضغ الحلوى يفطر، أما لو جعلها في فمه ثم لفظها ولا بلع شيء ما يضره، لكن ما دام يعلج ويبلع، هو مثل من يعلج الحلوى، أو التمر ويبلع. نعم.\nالمقدم: جزاكم الله خيراً، إذاً بعض الكتب التي أوردت هذا الحكم ......... ؟\nالشيخ: غلط، هذا غلط. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8398/حكم-مضغ-اللبان-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31011.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":10689,"question":"الأخت في الله: (ل. ر. ع) من الرياض تسأل أيضاً وتقول: ما حكم من تعاطى مفسداً من مفسدات الصوم جاهلاً بالحكم؟ هل عليه إعادة صومه؟","title":"حكم من تعاطى مبطلاً من مبطلات الصوم جاهلاً بالحكم","answer":"الجواب: نعم، عليه أن يعيد الصيام، كمن أكل يظن أنه لا حرج في الأكل في نهار الصيام المفترض أو جامع فإنه يقضي؛ لأنه مفرط بالتساهل وعدم التفقه في الدين، بخلاف الناسي فلا شيء عليه، لو أكل ناسياً أو شرب ناسياً فلا شيء عليه، كما قال عليه الصلاة والسلام: من نسي وهو صائم فأكل أو شرب فليتم صومه، فإنما أطعمه الله وسقاه، وفي اللفظ الآخر: من أفطر في رمضان ناسياً فلا قضاء عليه ولا كفارة، فإذا كان تعاطيه المفطر عن نسيان فإن صومه صحيح، أما إذا أكل أو شرب أو جامع يزعم أنه جاهل بالحكم فإنه يؤمر بالقضاء؛ لأنه في هذه الحالة يعتبر مفرطاً ومتساهلاً، وكان الواجب عليه أن يسأل، ولأن هذه الأمور مما اشتهر بين المسلمين وعرفه المسلمون، فدعوى الجهل فيه بعيد، دعوى الجهل في هذا بعيدة جداً. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8854/حكم-من-تعاطى-مبطلا-من-مبطلات-الصوم-جاهلا-بالحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33004.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":11490,"question":"بعد هذا رسالة بعث بها المستمع هاني عبيد الحسين من الجمهورية العربية السورية محافظة حماة، أخونا له قضية يقول فيها: إنني أعاني من مرض في أنفي، ويدعى الجيوب، وإنني لا أستطيع الأكل إذا لم أستعمل دواءً يسمى ..... والقصد من ذلك هو أنني في العام الماضي، وفي شهر الصيام صمت نهارًا، وعندما حل الفطر لم أستطع أكل لقمة واحدة بسبب عدم استخدام الدواء؛ لأنه يفتح المجاري التنفسية، ويسهل للمرء أن يأكل بحرية، ولم أستطع صيام الشهر الماضي بسبب ذلك المرض، وإني أخاف الله العظيم ولا أريد أن أعصيه بشيء، فهل يجوز لي استخدام الدواء قبل حلول الفطر بحوالي نصف ساعة، وهي قطرة في الأنف، واعلموا أني مضطر إلى ذلك، وإذا لم أستخدمه لا أستطيع الصوم، وهذا المرض يجرى له عملية جراحية، ولكن لا توجد لدي تكاليف العملية الجراحية، وإذا انتظرت إلى حلول الفطر ووضعت القطرة؛ فإني سأبقى مدة حوالي نصف ساعة حتى أستطيع الطعام، وأنا أعلم أن تعجيل الفطر واجب، فما هو توجيه سماحة الشيخ؟ هل أستطيع استعمال القطرة الأنفية قبل حلول الفطور بنصف ساعة؛ لأني مضطر؟ جزاكم الله خيرًا.","title":"حكم تعاطي المريض دواء قبل الإفطار في رمضان","answer":"الجواب:  ليس لك ذلك، ولو أخرت، ليس لك ذلك، ولو أخرت الإفطار والحمد لله، فأنت تؤخر حتى تكمل صومك فإذا كملت صومك فالحمد لله؛ لأن الرسول -عليه الصلاة والسلام؛ أخبر أن الأنف منفذ، ولهذا قال: وبالغ في الاستنشاق إلا أن تكون صائمًا فالأنف منفذ للماء والقطرات، فأنت أجل هذا الاستنشاق بالأنف بالقطرة؛ حتى يدخل الوقت، يعني: حتى تغيب الشمس، إلا إذا كان فيه قطرة خفيفة لا تصعد، ولا تنزل .... في الأنف فقط من غير صعود إلى الدماغ، ولا نزولًا إلى الحلق، وهذا لا يمكن أن تكون، يعني: القطرة لابد أن يكون لها نفوذًا. فالحاصل ما دام لها نفوذ في الدماغ، أو نزول؛ فأجلها حتى تغيب الشمس، ولو تأخرت، والحمد لله. المقدم: بارك الله فيكم، يقول: إنه سيتأخر نصف ساعة؟ الشيخ: لا يضر ولو ساعة، والحمد لله. المقدم: إذًا: على أخينا أن يصوم، وإذا ما أذن المغرب؛ فعليه أن يستعمل القطرة، وبعد نصف ساعة يأكل ويشرب. الشيخ: الحمد لله، نعم.  المقدم: بارك الله فيكم، جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9671/حكم-تعاطي-المريض-دواء-قبل-الافطار-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_383/38304.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":12257,"question":"تقول أيضًا: وحدث لي مثل ذلك في الصيام، حيث صمت أحد أيام رمضان قبل الموعد الصحيح للطهارة، هل علي كفارة؟ وما هي؟ وهل علي إعادة الصلوات التي صليتها في تلك الحالة؟","title":"حكم صيام المرأة حال حيضها","answer":"الجواب:  إذا كان معك الحيض، وصمت، فعليك إعادة ذلك اليوم الذي صمتيه، مادام الدم معك، والغسل الذي مع الدم؛ لا ينفع، لابد أن يكون الغسل بعد الطهارة، بعد رؤية القصة البيضاء، أو بعد ظهور وتبين النقاء بقطن ونحوه؛ حتى تري أن الحيض قد انقطع، ما بقي له أثر، فإذا صمت ومعك أثر الدم؛ فعليك القضاء، أما الصلاة فلا قضاء عليك، لكن عليك قضاء الصوم الذي وقع في حال الحيض. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10457/حكم-صيام-المراة-حال-حيضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_449/44908.mp3","categories":["الحيض والنفاس","مفسدات الصيام","قضايا المرأة"]},{"id":12719,"question":"ما هو رأيكم فيمن يتناولون الشمة وهم صيام، ويقولون: إنها لا تتسرب إلى الداخل، هل يؤثر ذلكم على صيامهم؟","title":"هل استعمال الشمة والدخان جائز للصائم؟","answer":"الجواب:  الظاهر أنه يجب المنع من ذلك، الشمة والدخان مثل سعوط العود، العود الذي هو طيب يمنع، فكيف بالدخان والشمة من باب أولى. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10932/هل-استعمال-الشمة-والدخان-جاىز-للصاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46007.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":13212,"question":"يقول هذا السائل: صمت رمضان، وأفطرت يومًا واحدًا فيه بغير عذر، وتبت إلى الله  وقضيت هذا اليوم من غير تأخير، والحمد لله، فهل علي مع صومي هذا اليوم كفارة، وجزاكم الله خيرًا؟","title":"حكم من أفطر في رمضان متعمداً من غير عذر","answer":"الجواب: إذا كان إفطارك بغير الجماع؛ فليس عليك كفارة، عليك التوبة -والحمد لله- والقضاء، إما إذا كان بجماع جامعت زوجتك، أو جماعًا محرمًا -نعوذ بالله- فعليك الكفارة، مع قضاء اليوم، ومع التوبة، عليك الكفارة، وهي عتق رقبة مؤمنة، فإن عجزت؛ تصوم شهرين متتابعين، ستين يومًا، شهرين متتابعين، فإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا، كل مسكين له نصف الصاع، يعني: تسعين كيلو، كل مسكين له كيلو ونصف كفارة إذا كنت جامعت في رمضان، سواءً زوجتك، أو غيرها، نعوذ بالله من الشيطان. فالحاصل: أن الجماع يوجب الكفارة مع قضاء اليوم، أما إفطار بالأكل، أو الشرب، ونحو ذلك، لكن من غير جماع؛ هذا يوجب القضاء فقط، والتوبة، القضاء والتوبة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11493/حكم-من-افطر-في-رمضان-متعمدا-من-غير-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52007.mp3","categories":["مفسدات الصيام","قضاء الصيام"]},{"id":13822,"question":"السائل معاوية آدم له هذا السؤال عن صيام رمضان يقول: كنت نائم وعندما حان وقت السحور قمت للسحور، وبعد السحور بخمس دقائق أقيمت الصلاة، فهل علي يوم؟ أم علي قضاء؟ مع العلم بأنني لم أسمع الأذان للفجر أفيدوني سماحة الشيخ؟","title":"ما يلزم من تناول السحور بعد أذان الفجر؟","answer":"الجواب: إذا كان الذي أقام الصلاة قد تأخر بعد الأذان المدة التي يجتهد فيها لوضوح الصبح وبيانه فأنت عليك القضاء، يستقضي عند جمهور أهل العلم، أما إذا كان أقام بعد الأذان إنسان يتعجل وأنت انتهيت بعد الأذان حالاً فلا يضرك؛ لأن الأذان على ظن الصبح ليس على رؤية الصبح، فإن الناس يؤذنون على التقويم والحساب فقد يكون أذانهم قبل الصبح بقليل.\nفالحاصل: أنه لا يتيقن طلوع الصبح، فأنت إذا أمسكت عند فراغ الأذان فالصوم صحيح إن شاء الله، لكن إذا تأخرت كثيرًا فإن الغالب أنك أدركت الصبح، فعليك القضاء عند أكثر أهل العلم. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12190/ما-يلزم-من-تناول-السحور-بعد-اذان-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53004.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":13929,"question":"في فقرتها الأخيرة في هذه الحلقة تقول: إنسان شرب في رمضان ظانًا بأن الأذان أذن ولم يؤذن، فماذا عليه في مثل هذه الحالة؟","title":"ما يلزم من شرب في رمضان يظن أنه أُذن للمغرب؟","answer":"الجواب: إذا عرف أنه شرب قبل الغروب يعيد، أما إذا كان يظن الغروب بسبب علامات ظاهرة فلا شيء عليه، أما إذا شرب يظن الغروب ثم بانت الشمس فإنه يقضي ذلك اليوم على الصحيح عند جمهور أهل العلم يقضي هذا اليوم، وهذا هو الأحوط، وبعض أهل العلم لا يراه يقضي؛ لأنه معذور لم يتعمد، ولكن الأقرب والأظهر أنه يقضي، وهكذا لو أكل بعد الفجر يحسب أنه ليل فبان أنه أكل في النهار يقضي، هذا هو الأرجح. نعم.\nالمقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/12307/ما-يلزم-من-شرب-في-رمضان-يظن-انه-اذن-للمغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53822.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":14067,"question":"يقول: صادف في رمضان أن أكلنا وشربنا متعمدين بعد أذان الفجر، وقد حصل نقاش طويل بيننا في هذه المسألة نرجو أن توجهونا كيف نتصرف؟ جزاكم الله خيرًا.","title":"ما يلزم من أكل بعد الفجر متعمدًا في رمضان؟","answer":"الجواب: عليكم التوبة والقضاء.. عليكم التوبة والقضاء؛ لأن الأذان يتحرى الوقت؛ والنبي عليه السلام قال: إن بلالًا يؤذن بليل فكلوا واشربوا حتى يؤذن ابن أم مكتوم، وذلك أن ابن أم مكتوم كان يؤذن على الصبح، والأوقاف مجتهدة قد هيئت لهم تقويمًا يسيرون عليه، فإذا أكلتم بعد الأذان فأنتم مخاطرون متلاعبون فعليكم القضاء.\nأما مع الأذان وحين الأذان عند الحاجة فلا بأس، أما بعد الأذان فالواجب القضاء، وعدم التساهل في هذا الأمر، نسأل الله للجميع الهداية.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12496/ما-يلزم-من-اكل-بعد-الفجر-متعمدا-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48408.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":14111,"question":"يسأل أخونا حول نفس الموضوع فيقول: هل يجوز لمن صلى صلاة الفجر في المسجد جماعة، يعني قبل طلوع الشمس بساعة وعشرين دقيقة أن يأكل أو يشرب وذلك في شهر رمضان؛ لأنه لم يتبين الخيط الأبيض من الخيط الأسود، نرجو الإجابة مفصلة مع الأدلة؟ جزاكم الله خيرًا.","title":"هل يجوز الأكل والشرب للصائم بعد أذان الفجر؟","answer":"الجواب: ليس له أن يأكل ولا يشرب بل عليه أن يمسك وأن يصوم؛ لأن الظاهر أن المؤذنين تحروا الأذان وتحروا طلوع الفجر، ثم قد صلى، كيف يصلي ويأكل؟! الصلاة أعظم، إذا كان الفجر ما طلع ما صحت الصلاة، فكيف يصلي ثم يأكل؟! الواجب التحري للصلاة؛ لأنها أعظم من الصوم، فرض الصلاة أعظم من فرض الصوم، فالواجب التحري فإذا غلب على ظنه دخول وقت الفجر صلى الفجر وامتنع من الأكل والشرب، وليس له أن يأكل ويشرب وهو يظن طلوع الفجر ويغلب عليه طلوع الفجر، والله يقول : وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الأَبْيَضُ مِنَ الْخَيْطِ الأَسْوَدِ مِنَ الْفَجْرِ[البقرة:187] والمعنى: حتى تتحققوا طلوع الفجر. فما دام عنده شك له أن يأكل ويشرب، لكن إذا كان في محل لا يظهر فيه طلوع الفجر مثل المدن التي فيها الأنوار فيعمل بالتقاويم المضبوطة والتحري وغلبة الظن، يكفي ذلك ويمتنع من الأكل والشرب. أما إذا كان في الصحراء التي ليس يحول بينه وبين الفجر فيها شيء فإنه يأكل ويشرب حتى يعلم الفجر، حتى يعلم طلوع الفجر كما هو نص القرآن الكريم. أما أن يصلي الفجر ثم يأكل هذا غلط عظيم، ليس له أن يصلي إلا بعد طلوع الفجر، ومتى طلع الفجر باليقين أو بغلبة الظن حرم الأكل والشرب وجازت الصلاة. نسأل الله للجميع الهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12552/هل-يجوز-الاكل-والشرب-للصاىم-بعد-اذان-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61413.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":15129,"question":"سؤاله الآخر يعرض في الحقيقة مشكلة وقعت عليه في رمضان، يقول: يوجد عندي بنت متزوجة، وقد جاءت عندنا هي وزوجها في شهر رمضان، وبعدما صمنا أسبوعًا جاء زملاء زوج بنتي، وذهبوا إلى البر، وخالطهم الشيطان فأكلوا وشربوا، وجاء اليوم الثاني في الصباح -الذي هو زوج بنته- وقال لزوجته: يريد أن تعطيه أكل، فمنعت زوجته، وطلق، إنه يفطر وحلفت يمينًا ما تسوي له أكل، فأصبحت محتارة بين زوج بنتي وبين بنتي؛ لأنه طلق، وهي حلفت يمينًا، فأجبرت زوجة ولدي أن تسوي له أكلًا، فمنعت فغصبتها، وهي ليست راضية، وقامت وعملت له أكلًا، فأكل وشرب ونحن موجودين معه في البيت، ولكننا لم نأكل معه، فماذا يلزمنا هل علينا إثم أو يلزمنا صدقة؟أفيدونا، جزاكم الله عنا ألف خير.","title":"حكم الفطر في رمضان وحكم من أعان على ذلك","answer":"الجواب: لا شك أن الإفطار في رمضان بدون عذر شرعي كبيرة من الكبائر، ومنكر من المنكرات العظيمة إذا كان من غير عذر شرعي.  أما إذا كان بعذر السفر إذا سافروا ما يعد سفرًا، وهو ما يعادل ثمانين كيلو تقريبًا، أو سبعين كيلو تقريبًا، مسافة يوم وليلة تقريبًا، بالمطايا والأقدام، فما يعادل ذلك ويقاربه يسمى سفرًا، ولا حرج في الإفطار فيه. أما ما كان في البيت أو في ضواحي البلد، ولا يسمى سفرًا؛ فهذا الإفطار فيه كبيرة من الكبائر، والذي يعين المفطر على إفطاره شاركه في الإثم؛ لأن الله سبحانه يقول: وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2] فالذي يساعد من أفطر في رمضان بغير عذر بتقديم الطعام أو القهوة أو الشاي أو غير ذلك من الأشربة أو المطعومات؛ آثم مشارك للمفطر في الإثم، لكن صومه صحيح، لا يبطل صومه بالمعاونة، ولكن يكون آثمًا، وعليه التوبة إلى الله. وعليك -أيها الأخ- عند غصبك البنت على صنع الطعام، عليك التوبة إلى الله، فإنك قد أخطأت حين أمرتها بصنع الطعام له، فهي قد أحسنت وأصابت في عدم طاعته؛ لأنه لا طاعة لمخلوق في معصية الخالق، والنبي  قال: إنما الطاعة في المعروف فإذا أمرها زوجها أن تقدم له طعامًا في الصوم صوم رمضان، وهو ليس به عذر، ليس بمريض لا عذر له؛ فهذا حرام ومنكر، ليس له الإفطار، وليس له أمر زوجته بإعداد فطور له، وليس لها أن تعينه على ما حرم الله، ولو غضب، ولو طلق، لا يجوز لها أن تعينه على ما حرم الله عليه وعليها، وطاعة الله مقدمة على طاعة الزوج، وعلى طاعة الأب، وعلى طاعة السلطان، وعلى طاعة الأمير؛ لأن الرسول ﷺ قال: إنما الطاعة في المعروف وقال أيضًا -عليه الصلاة والسلام-: لا طاعة لمخلوق في معصية الخالق نعم، الله المستعان.\nالمقدم: لكن ربما أن الذي قرأناه الآن في رسالة المستمع (ع. ل. هـ) من بلاد غامد يتضح أن الزوج مسافر، وأن زملاءه الذين أتوا إليه مسافرين أيضًا؟\nالشيخ: لا، يقول في البيت........، في البيت.\nالمقدم: إي نعم.\nالشيخ: أمرها في البيت بعدما رجعوا. المقدم: لا هم لا يزالون في سفر في بلاد غامد في سفر؛ لأنه يقول: قدمت لنا بنتي وزوجها زارونا في نهار رمضان، وزاره أيضًا زملاؤه فأصبحوا الجميع مسافرين.\nالشيخ: إذا كانوا مسافرين، وقد عزموا على الإقامة أكثر من أربعة أيام؛ فإنه يلزمهم الصوم هذا الأرجح، وهو قول جمهور أهل العلم: إذا كانوا قد عزموا على الإقامة أكثر من أربعة أيام عند أصحابهم؛ يصوموا معهم، أما في أقل من أربعة أيام، أربعة أيام فأقل فلا يلزمه الصوم إذا كانوا مسافرين، مروا عليهم زوارًا؛ فلا يلزمهم الصوم، وإن صاموا فلا بأس، ولا حرج، أما إذا كانوا قد أرادوا الإقامة عندهم أكثر من أربعة أيام؛ فالذي ينبغي في هذه الحال هو الصوم خروجًا من خلاف العلماء، وعملًا بقول الأكثر؛ ولأن الأصل الصوم، وشك في إجازة الإفطار، نعم.","link":"https://binbaz.org.sa/fatwas/13630/حكم-الفطر-في-رمضان-وحكم-من-اعان-على-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_657/nour_65702.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":15204,"question":"السؤال الآخر ورد من السائل أبو تركي من الرياض، يقول: أنا رجل أسكن في بيت لوحدي، وذات مرة قمت لأتسحر فنظرت في الساعة، فإذا هي الثالثة صباحًا، بمعنى أن هناك متسعًا من الوقت للسحور، وليس في البيت منفذ لضوء النهار، وفعلاً تسحرت، وحينما أردت الخروج للصلاة -صلاة الفجر- تبين لي أن النهار قد طلع، وأن الناس قد صلوا الفجر، وعادوا إلى منازلهم، فماذا يجب علي في هذه الحالة القضاء أم الكفارة؟ وهل أكمل صيام هذا اليوم أم أفطره؟","title":"حكم من تسحر بعد الفجر ظانًا أنه ما زال الليل","answer":"الجواب: عليك إكمال الصوم في رمضان إذا كان رمضان عليك إكمال الصوم، وعليك القضاء على الصحيح عند أكثر أهل العلم؛ لأنك تساهلت، ولم تعتن بمعرفة أسباب ظهور الصبح، بل تساهلت، ثم تبين لك أنك أكلت في النهار، فعليك القضاء في أصح قولي العلماء، وعند أكثر أهل العلم مع الإمساك في رمضان. أما إذا كان الصوم في غير رمضان، مثل صوم كفارة أو صوم نذر، فهذا لا تمسك تقضي يومًا مكانه، إذا علمت أنك أكلت في النهار تفطر ذلك اليوم، وتقضي يومًا مكانه، والحمد لله.  أما إن كان نافلة فالأمر واسع، النافلة أمرها واسع، لك أن تفطر؛ لأنه نافلة، ولك أن تصوم من جديد، لكن ما دام أكلت في النهار، لا تصم من جديد، بل تفطر؛ لأنه يوم لا يعتد به بسبب الأكل الذي فيه في النهار. فالحاصل: أنه إذا كان صوم رمضان عليك أن تمسك، وتقضي ذلك اليوم، أما إذا كان صوم كفارة، أو صوم نذر، أو صوم نافلة، فإنك تفطره وتقضي يومًا مكانه، بدل الكفارة والنذر، نعم.\nالمقدم: وإذا كان عن قضاء فريضة؟\nالشيخ: ولو كان عن قضاء رمضان كذلك له أن يفطر. المقدم: يعتبر كالنافلة؟ الشيخ: لأن زمانه ما هو محترم، بخلاف زمان رمضان، أما زمن القضاء فإذا أكل في النهار يحسبه ليلًا فإنه يفطر ويقضي بدل ذلك اليوم، ولا يكمل، لا يلزمه الإكمال؛ لأنه لا يفيده شيئًا. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13695/حكم-من-تسحر-بعد-الفجر-ظانا-انه-ما-زال-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_671/nour_67102.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":15899,"question":"يقول: في ليلة من ليالي رمضان قمنا للسحور، ولكنا قمنا متأخرين، والبعض قام متأخرًا كثيرًا، فأكل فطلع الفجر، وهو ما زال يأكل، ولم يكف عن ذلك، فما حكم صومه؟ وما حكم من إذا أذن للكفاف لم يترك الأكل؟ أفيدونا، أفادكم الله.","title":"حكم استمرار الصائم في الأكل أثناء أذان الفجر","answer":"الجواب: من أكل بعد طلوع الفجر عليه أن يعيد، وعليه أن يقضي مع التوبة، أما من أكل وهو يؤذن أو في مكان يشك فيه بطلوع الفجر ما اتضح له الفجر فلا حرج عليه، لكن إذا كان أذن المؤذن يترك، الأذان يوجب الانكفاف عن تناول الطعام والشراب.  لكن لو أكل شيئًا من الطعام أو شرب شيئًا من الماء وهو يؤذن، ولا يعلم بطلوع الفجر فإنه لا حرج؛ لأن المؤذنين يؤذنون على التقويم وعلى ظن الصبح، وليس على يقين الصبح، فإذا شرب شيئًا عند الأذان أو أكل شيئًا عند الأذان فإنه لا يضر -إن شاء الله- إلا إذا كان في مكان يعلم طلوع الفجر، فإنه يمسك، أو في مكان يعلم أن المؤذن إنما يؤذن بعد طلوع الفجر، فإنه يمسك إذا سمع الأذان، أما الأذان المعروف الآن الذي على التقويم هذا لا حرج فيه أن يتناول ما في يده من طعام أو شراب وقت الأذان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14489/حكم-استمرار-الصاىم-في-الاكل-اثناء-اذان-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74516.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":15936,"question":"السائلة تقول سماحة الشيخ: أريد أن أعرف حكم الشرع في نظركم فيمن وقع على زوجته في رمضان دون إرادتها، وهي كارهة لذلك. تقول السائلة: فقد كنت شبه نائمة عندما سمعت صوت المسجد ليؤدون الصلاة، والذي حدث بعد سماعي لصوت المسجد بقليل بأن زوجي أيضًا لا يدري هل كان يعلم بالأذان أم لا؟ وأعتقد أنه كان نائمًا، فماذا أفعل؟ وهل علي كفارة وأنا كارهة لما وقع؟ وكنت من قبل أخشى الوقوع في هذا، وأستبعده إذا قرأت حكم ذلك في الكتب، هل على زوجي كفارة؟ أنا عندي أطفال، وأقوم بواجباتهم وشؤونهم وشؤون زوجي، فقد يكون الصيام -يا سماحة الشيخ- شهرين يكلف علي، مع أعمال المنزل، ومشاكل الأطفال، وهل يكون صيام الشهرين متتابع أم لا؟ مأجورين.","title":"حكم من واقع أهله في نهار رمضان","answer":"الجواب: عليكما جميعًا التوبة إلى الله أولًا، والندم، والإقلاع من هذا الذنب، وعدم العودة إليه؛ لأن هذا منكر عظيم، الجماع في رمضان منكر عظيم، ومن كبائر الذنوب، فالواجب الحذر من ذلك، والتوبة إلى الله مما وقع، عليك وعلى زوجك جميعًا التوبة إلى الله، وعليكما جميعًا كفارة، وهي: عتق رقبة، لكن الرقاب غير متيسرة الآن، فإن لم يستطع العتق فصيام شهرين متتابعين -ستين يومًا­- لا بد من ذلك، فإذا عجزتما عن الصيام فإطعام ستين مسكينًا، الذي لا يستطيع على الصيام يطعم ستين مسكينًا، أنت وزوجك، ستين مسكينًا؛ كل مسكين له كيلو ونصف، تسعين كيلو، كل واحد له كيلو ونصف من قوت البلد: من تمر أو أرز أو حنطة؛ هذا هو الواجب على من أتى زوجته على الزوج وعلى الزوجة. وكونك تكرهين ما يسقط عنك الكفارة، الواجب منعه، الواجب منعه بالقوة، وعدم السماح له، فإذا قهرك بالقوة والضرب كنت معذورة، أما مجرد الكراهة فقط ما يكفي، عليكما الكفارة جميعًا، والتوبة إلى الله جميعًا وقضاء اليوم، ونسأل الله للجميع الهداية.\nالمقدم: أحسن الله إليكم، الاختيار الشهرين -يا سماحة الشيخ- أو الصيام هل هي مخيرة بذلك؟\nالشيخ: الترتيب من عجز عن الصيام ينتقل إلى الطعام، ومن قدر على الصيام يصوم شهرين متتابعين -ستين يومًا- فإن عجز، عجز لكونها ترضع، أو لمشاغلها الكثيرة، أو لمرض ينتقل إلى الإطعام، وهكذا الرجل إذا شق عليه لعمل يعمله أو لمرض، أو نحو ذلك؛ انتقل إلى الإطعام، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14539/حكم-من-واقع-اهله-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57806.mp3","categories":["الجماع في نهار رمضان","مفسدات الصيام"]},{"id":16241,"question":"تقول: إنني في شهر رمضان استفرغت عشرة أيام، ولم أفطر، هل علي القضاء، أم لا؟ جزاكم الله خيرًا.","title":"حكم القضاء على من استقاء في نهار رمضان","answer":"الجواب:  إن كان الاستفراغ باختيارك؛ فعليك القضاء، لقول النبي ﷺ: من ذرعه القيء؛ فلا قضاء عليه، ومن استقاء؛ فعليه القضاء أما إذا كان غلبك، ولم تختاري ذلك، ولكن غلبك، وخرج بغير اختيارك؛ فليس عليك قضاء لهذا الحديث المذكور، أما إن كنت استفرغت أنت بنفسك اختيارًا منك في الأيام العشرة؛ فإنك تقضين جميع الأيام؛ لأن الصوم بطل بذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14930/حكم-القضاء-على-من-استقاء-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80703.mp3","categories":["قضاء الصيام","مفسدات الصيام"]},{"id":16268,"question":"يقول السائل في هذا  إذا سمع الإنسان الأذان في رمضان من الراديو، ثم أفطر بناءً على أن هذا الأذان لبلده، وتبين أنه لبلد آخر يؤذن قبل بلده، هل يقضي هذا اليوم يا سماحة الشيخ؟","title":"حكم من أفطر على أذان في المذياع يظنه أذان بلده","answer":"الجواب: إذا علم أنه أفطر قبل غروب الشمس؛ يقضي، عليه قضاء، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14955/حكم-من-افطر-على-اذان-في-المذياع-يظنه-اذان-بلده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58106.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":16787,"question":"هذا السائل يا سماحة الشيخ من اليمن تعز، يقول: ما هي مفسدات الصوم بغير إرادة الإنسان؟","title":"حكم الصائم إذا تناول مفطرًا بغير إرادته","answer":"الجواب: المفطرات إذا حصل له ما يفطر الصائم باختياره، كأن يشرب، أو يأكل، أو يجامع، أو ما أشبه ذلك؛ أفطر، أما إن كان بغير اختياره مثل أكره على إدخال الماء في فيه بالقوة، والظلم هذا ما يفطر، أو نسي، شرب ناسيًا لا يفطر، أما إذا اختار، شرب وهو يعلم أنه صائم؛ أفطر، أكل وهو يعلم أنه صائم متعمدًا؛ أفطر، جامع كذلك أفطر، أما إذا كان لا.. مكره، الله يقول: مَنْ كَفَرَ بِاللَّهِ مِنْ بَعْدِ إِيمَانِهِ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالإِيمَانِ [النحل:106].  إذا كان إسلامه لا يبطل، إذا كفر بعد الإيمان مكرهًا، وقلبه مطمئن؛ لا يكفر، فمن باب أولى لا يفطر، فلو أن إنسانًا جبره ناس على شرب الماء، أو صبوا في فمه الماء، أو أدخلوا في فمه ما يفطره بالقوة؛ لا يضره ما دام لم يقصد ذلك، وإنما أجبروه عليه؛ فإنه لا يفطر بذلك؛ لأنه مكره. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15531/حكم-الصاىم-اذا-تناول-مفطرا-بغير-ارادته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_585/58508.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":17287,"question":"الأخوات أم أمل، وأم رقية، وأم عبدالرحمن من تبوك لهن مجموعة من الأسئلة، سؤالي الأول سماحة الشيخ تذكر إحداهن وتقول: بأنها فتاة تبلغ من العمر إحدى وعشرين عامًا، وكانت تقول سابقًا ترعى الغنم في رمضان، وكانت تشرب دون أن يعلم بها أحد إلا الله  وذلك جهلًا منها تقول، والآن تذكرت تلك الأيام، وتريد الآن أن تقضي ما عليها، لكن لا تدري كم عدد هذه الأيام، هل هي قليلة، أم كثيرة؟ ولم يغلب على ظنها كم عدد هذه الأيام؟ تقول: وجهوني يا سماحة الشيخ؟","title":"حكم الفطر في رمضان جهلًا","answer":"الجواب: إذا كان ذلك بعدما بلغت وأرشدت؛ عليها القضاء، أما إذا كان ذلك قبل البلوغ، قبل أن تكمل خمسة عشر سنة، قبل أن تحيض، إذا كان وهي صغيرة؛ ما عليها قضاء، أما إذا كان بعد البلوغ فعليها القضاء بالتحري بالتحري .. عشره أيام.. عشرين يومًا.. ثلاثين يومًا، تتحرى حسب طاقتها، وتصوم. المقدم: حفظكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16131/حكم-الفطر-في-رمضان-جهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59307.mp3","categories":["مفسدات الصيام","قضاء الصيام"]},{"id":17641,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، في أحد أسئلته في هذه الرسالة يقول: في ليلةٍ من ليالي رمضان صحونا ومؤذن الفجر يؤذن، فتسحرنا، وصمنا، فهل صيامنا صحيح؟ أم نقضي ذلك اليوم؟ جزاكم الله خيرًا.","title":"حكم من تسحر والمؤذن يؤذن للفجر","answer":"الجواب: إذا كنتم لا تعلمون طلوع الفجر، وتشكون في طلوع الفجر، فالصيام صحيح، أما إذا كنتم تعلمون أن الفجر قد طلع، فعليكم القضاء، والمؤذن يؤذن على تقويم، على ظن الفجر، وليس على يقين الفجر، بل على الظن، أو على التقويم الذي عنده، فمن عرف طلوع الفجر؛ حرم عليه الأكل، وإلا فله الأكل عند الشك، والأحوط له أن يتقدم للأكل قبل الأذان، حتى يستبرئ لصيامه، ويبتعد عن الشبهة، وإذا كان أكله بعد الأذان بوقت طويل، فالأحوط له القضاء، أما إذا كان شيئًا يسيرًا، دقيقة، دقيقتين، أو مع الأذان، فلا حرج إن شاء الله، إذا لم يعلم طلوع الفجر. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16563/حكم-من-تسحر-والموذن-يوذن-للفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_726/nour_72608.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":17690,"question":"هذا سائل يا سماحة الشيخ يقول: شخص عليه صيام شهرين متتابعين من خطأ ارتكبه في نهار رمضان عن جهل، ولم يستطع الصوم لعذر شرعي من الحالة الصحية كمرض، ودار عليه الحول، وأصبح عليه الصيام مع إطعام، وهو حتى الآن لم يستطع الصوم؛ وقد نصحه بعض الأشخاص بأن يطعم ستين مسكينًا.. والسؤال يا سماحة الشيخ: هل أصبحت عليه الكفارة بكفارتين، بأن يطعم في اليوم مسكينين، أم تكفي كفارة واحدة؟","title":"حكم من عجز عن صيام كفارة الجماع","answer":"الجواب: كفارة واحدة تكفي، إذا عجز عن الصيام بسبب الجماع في رمضان يطعم ستين مسكينًا، وليس عليه سوى ذلك؛ كل مسكين نصف صاع، كيلو ونصف من التمر أو الرز أو غيرها من قوت البلد، ويكفي والحمد لله.","link":"https://binbaz.org.sa/fatwas/16632/حكم-من-عجز-عن-صيام-كفارة-الجماع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59519.mp3","categories":["الجماع في نهار رمضان","مفسدات الصيام"]},{"id":18976,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (ب. ط. ت) أخونا له سؤالان:السؤال الأول يقول: لقد تزوجت قبل سبعة أعوام، وفي أواخر شعبان، وقد جامعت زوجتي في بعض أيام رمضان لجهل مني في ذلك الوقت، ومن الشيطان لعنه الله، الصيام صعب علي لعدم معرفتي بعدد الأيام، وكذلك العتق، فهل يجوز أن أشتري أكياس رز وأعطيها لإحدى الجمعيات الخيرية كصدقة، كما قلت لا أعرف الأيام التي صار فيها الجماع، هل ما ذكرته لكم صحيح ويعد كفارة، أم أنكم توجهوني بتوجيه آخر؟جزاكم الله خيرًا.","title":"حكم من جامع في نهار رمضان مرارًا ونسي عددها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فلا ريب أن المؤمن يحرم عليه أن يجامع في رمضان في نهار رمضان، بل يجب عليه أن يمتنع من ذلك؛ لأن الجماع من المفطرات، كما أنه لا يأكل ولا يشرب فهكذا لا يجامع، فإذا وقع منه ذلك وجب عليه أمور ثلاثة: أحدها: التوبة إلى الله ؛ لأن ذلك معصية، والتوبة واجبة من كل معصية. الأمر الثاني: قضاء اليوم الذي وقع فيه الجماع. الأمر الثالث: الكفارة، والكفارة مرتبة، أولها: عتق رقبة مؤمنة، فإن لم يستطع صام شهرين متتابعين، فإن لم يستطع أطعم ستين مسكينًا، لكل مسكين نصف صاع من قوت البلد، من تمر أو رز أو غيرهما. هذا هو الواجب على من جامع زوجته في نهار رمضان، والصيام عليه واجب، وعليها كذلك، أما لو جامعها في السفر، فهذا معروف المسافر له الإفطار بالجماع وغيره، لكن إذا جامعها وهما مقيمان يلزمهما الصيام، فإنه يلزمه هذه الأمور الثلاثة: التوبة، وقضاء اليوم، والكفارة، وهي مثله إذا كانت مطاوعة، أما إذا أكرهها بالقوة والشدة، ولم تستطع التخلص منه، بل أجبرها فلا شيء عليها، وإنما الكفارة عليه هو. وإذا كان كل منهما يعجز عن العتق، وعن الصيام، فإنه يجزئه الإطعام لستين مسكينًا ثلاثين صاعًا كل صاع بين اثنين، من قوت البلد، من تمر أو بر أو أرز، ولا بد من توزيعه بين الستين، ولو أن الجمعية الخيرية التزمت بذلك وفرقته بين ستين مسكينًا فلا بأس إذا اطمئن إليها، ووثق من القائمين عليها، وأنهم يوزعون ما يعطيهم على ستين مسكينًا فلا بأس، إذا كان عجز عن العتق والصيام، والمرأة مثله كما تقدم. وإذا كنت لا تضبط الأيام فعليك التحري، التحري والظن، فإذا ظننت أنها خمسة صمت خمسة، ظننت أنها ستة صمت ستة، وهكذا تعمل بالاحتياط والظن الغالب، ويكفي ذلكفَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن: 16]. وإذا كان المجامع جاهلًا أو ناسيًا، فهذا محل نظر، أما الجهل فالذي ينبغي عدم اعتباره؛ لأن الأمر واضح بين المسلمين، وليس أمرًا خفيًا، يعرفه المسلمون أن الصائم لا يجامع أهله في رمضان، فينبغي عدم التعلق بالجهل، وعدم الاعتذار بالجهل، بل عليك أن تفعل ما ذكرنا. أما النسيان فالصواب أنه معذور إذا نسي الإنسان؛ لأن النسيان ليس بالاختيار، بل أمر يقع على الإنسان ويغلب عليه وليس باختياره، وقد قال -عليه الصلاة والسلام-: من نسي وهو صائم فأكل أو شرب فليتم صومه، فإنما أطعمه الله وسقاه متفق عليه، ورواه الحاكم وجماعة بلفظ: من أفطر في رمضان ناسيًا فلا قضاء عليه ولا كفارة فالناسي معذور على الصحيح إذا صدق في كونه ناسيًا؛ لأن النسيان ليس في اختيار الإنسان رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286]، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18122/حكم-من-جامع-في-نهار-رمضان-مرارا-ونسي-عددها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_925/nour_92501.mp3","categories":["الجماع في نهار رمضان","مفسدات الصيام"]},{"id":19477,"question":"هذا أخونا السائل: أبو عبد الله من الرياض يقول: سماحة الشيخ! حفظكم الله، وسدد خطاكم، ذهبت أنا والوالدة إلى مكة المكرمة لأداء فريضة العمرة، وبعد وصولنا إلى مكة آخر الليل قررنا أن نستريح في السكن بعض الوقت، وقبل صلاة الفجر فأخذنا النوم فلما استيقظنا سألتني الوالدة: هل أذن الفجر؟ فقلت لها: لا، وأنا لا أعلم، فأكلت علاجًا كان معها، فتبين لنا بعد ذلك بأن أذان الفجر قد أذن منذ عشرين دقيقة، فماذا يجب على الوالدة؟ وهل يلزمني شيء؟","title":"حكم من شرب بعد أذان الفجر من رمضان جاهلًا","answer":"الجواب: عليها أن تقضي اليوم من رمضان، وأنت عليك الاستغفار عن إفتائها بغير علم، تقول: ما أذن وأنت ما تدري، عليك التوبة والاستغفار وعليها القضاء هي. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18725/حكم-من-شرب-بعد-اذان-الفجر-من-رمضان-جاهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93913.mp3","categories":["مفسدات الصيام","ما لا يفسد الصيام"]},{"id":19504,"question":"هذه سائلة تقول سماحة الشيخ: فتاة بلغها في النصف من رمضان الحيض، ولم تخبر الأهل، فهل عليها قضاء أو قضاء مع كفارة؟","title":"الواجب على المرأة التي أتاها الحيض في رمضان","answer":"الجواب: عليها القضاء، وإذا كان القضاء تأخر بعد رمضان آخر عليها القضاء مع إطعام مسكين عن كل يوم زيادة، إذا تأخر القضاء إلى رمضان آخر، وعليها التوبة إلى الله أيضًا من تساهلها وعدم صيامها. نعم.","link":"https://binbaz.org.sa/fatwas/18763/الواجب-على-المراة-التي-اتاها-الحيض-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93930.mp3","categories":["الحيض والنفاس","مفسدات الصيام","قضايا المرأة"]}]
